package org.brightstats.model;
import java.util.*;
import com.google.gson.*;
import org.brightstats.model.TypedDiagram.*;
import org.brightstats.model.ElementType.Family;
import org.brightstats.stats.*;

/** Explicit root opt-in binds copula markers and polynomial requests to the adjusted system. */
public final class DiagramAdjustedCopula {
    private DiagramAdjustedCopula(){}
    public record Compiled(Document document,ComponentScores.Model component,AdjustedCopula.Model system,double[][] observations,Map<Integer,Integer> binaryBindings,List<String> warnings){public Compiled{observations=Matrices.copy(observations);binaryBindings=Collections.unmodifiableMap(new LinkedHashMap<>(binaryBindings));warnings=List.copyOf(warnings);}@Override public double[][] observations(){return Matrices.copy(observations);}}
    public static boolean requested(Document document){return DiagramModels.string(document.node(document.root()).properties(),"copulaEstimator","").equals("ADJUSTED_2025");}
    public static Compiled compile(Document document,List<String> columns,double[][] data){if(!requested(document))throw new IllegalArgumentException("Select root copulaEstimator=ADJUSTED_2025 explicitly.");if(document.family()==Family.CBSEM)throw new IllegalArgumentException("Adjusted score/observed copula systems are not a covariance-SEM likelihood estimator.");int width=Matrices.width(data,3);if(width!=columns.size())throw new IllegalArgumentException("Column names and data width differ.");Set<String> markers=new HashSet<>();for(var node:document.nodes())if(node.type()==ElementType.GAUSSIAN_COPULA)markers.add(node.id());Document base=document.remove(markers);var properties=document.node(document.root()).properties();Map<String,Integer> identities;Map<Integer,Integer> physical=new LinkedHashMap<>();List<String> names;List<PlsSem.Edge> paths;List<NonlinearPls.Extension> extensions;ComponentScores.Model component=null;double[][] source=data;List<String>warnings=new ArrayList<>();
        switch(document.family()){
            case PLS->{var model=DiagramModels.pls(base,columns);identities=model.identities();names=model.blocks().stream().map(PlsSem.Block::name).toList();paths=model.edges();extensions=model.extensions();component=ComponentScores.Model.pls(model.blocks(),paths,org.brightstats.data.PlsModelInput.options(properties.get("plsOptions")));for(int j=0;j<model.blocks().size();j++)if(model.blocks().get(j).columns().length==1)physical.put(j,model.blocks().get(j).columns()[0]);}
            case GSCA->{var model=DiagramModels.gsca(base,columns);identities=model.identities();names=model.prepared().model().components();paths=new ArrayList<>();boolean[][] graph=model.prepared().model().paths();for(int a=0;a<graph.length;a++)for(int b=0;b<graph.length;b++)if(graph[a][b])paths.add(new PlsSem.Edge(a,b));extensions=model.extensions();var options=properties.has("gscaOptions")?new Gson().fromJson(properties.get("gscaOptions"),Gsca.Options.class):Gsca.Options.defaults();component=ComponentScores.Model.gsca(model.prepared().model(),options,model.prepared().columns());boolean[][] mask=model.prepared().model().weights();for(int j=0;j<names.size();j++){int count=0,column=-1;for(int row=0;row<mask.length;row++)if(mask[row][j]){count++;column=model.prepared().columns()[row];}if(count==1)physical.put(j,column);}}
            case PROCESS->{var process=DiagramProcess.compile(base,columns,data);var options=org.brightstats.data.PolynomialInput.options(properties.get("processOptions"));if(options.metric()!=PathProcess.Metric.UNSTANDARDIZED)throw new IllegalArgumentException("The adjusted PROCESS contract uses raw fixed-composite units. Select processOptions.metric=UNSTANDARDIZED; other PROCESS metric analyses remain separate.");identities=process.identities();names=process.polynomialBlocks().stream().map(PlsSem.Block::name).toList();paths=new ArrayList<>(process.polynomialPaths());extensions=process.extensions();double[][] derived=process.observations();source=new double[data.length][names.size()];for(int j=0;j<names.size();j++){int column=process.polynomialBlocks().get(j).columns()[0];physical.put(j,j);for(int row=0;row<data.length;row++)source[row][j]=derived[row][column];}if(options.considerControls()){Set<Integer> targets=new TreeSet<>();for(var edge:paths)targets.add(edge.target());for(var term:extensions)targets.add(term.target());for(int control:process.model().controls()){int index=-1;for(int j=0;j<process.polynomialBlocks().size();j++)if(process.polynomialBlocks().get(j).columns()[0]==control)index=j;if(index<0)throw new IllegalArgumentException("PROCESS control binding is missing.");for(int target:targets){var edge=new PlsSem.Edge(index,target);if(index!=target&&!paths.contains(edge))paths.add(edge);}}}warnings.addAll(process.warnings());warnings.add("This adjusted PROCESS system uses fixed raw mean/sum composites. Case resampling preserves those row functions; no original-sample estimated score weights or transformations are reused.");}
            case REGRESSION->{var regression=DiagramModels.regression(base,columns);if(!regression.intercept())throw new IllegalArgumentException("The adjusted copula regression contract requires a connected intercept.");identities=new LinkedHashMap<>();names=new ArrayList<>();paths=new ArrayList<>();extensions=List.of();int[] predictors=regression.predictors();int target=predictors.length;source=new double[data.length][target+1];for(int j=0;j<target;j++){identities.put(regression.predictorNodes().get(j),j);names.add(columns.get(predictors[j]));physical.put(j,j);paths.add(new PlsSem.Edge(j,target));for(int row=0;row<data.length;row++)source[row][j]=data[row][predictors[j]];}identities.put(regression.responseNode(),target);names.add(columns.get(regression.response()));physical.put(target,target);for(int row=0;row<data.length;row++)source[row][target]=data[row][regression.response()];}
            default->throw new IllegalArgumentException("Unsupported adjusted-copula diagram family.");
        }
        List<PlsSem.Edge> normalized=NonlinearPls.normalizedPaths(names,paths,extensions);Map<Integer,Set<Integer>> requests=new TreeMap<>();Set<Integer> attachedTargets=new HashSet<>();boolean explicit=properties.has("adjustedCorrections");
        for(var marker:document.nodes())if(marker.type()==ElementType.GAUSSIAN_COPULA){var attached=document.links().stream().filter(link->link.source().equals(marker.id())&&link.type()==ElementType.CONNECTION_BETWEEN_GAUSSIAN_COPULA_AND_INDEPENT_TO_DEPENDENT_LV_CONNECTION).toList();if(attached.isEmpty())throw new IllegalArgumentException("Attach every copula marker to a model path.");for(var link:attached){var anchor=document.node(link.target());if(anchor.type()!=ElementType.DONGLE)throw new IllegalArgumentException("Copula attachments require a path anchor.");int target,sourceIndex=-1;if(document.family()==Family.REGRESSION){var edge=document.link(DiagramModels.string(anchor.properties(),"edge",null));String outcome=identities.entrySet().stream().filter(entry->entry.getValue()==names.size()-1).map(Map.Entry::getKey).findFirst().orElseThrow();String predictor=edge.source().equals(outcome)?edge.target():edge.target().equals(outcome)?edge.source():"";Integer index=identities.get(predictor);if(index==null)throw new IllegalArgumentException("Regression copula is not attached to a predictor path.");sourceIndex=index;target=names.size()-1;}else{var term=DiagramModels.anchorTerm(document,anchor,new HashSet<>());Integer index=identities.get(term.target());if(index==null)throw new IllegalArgumentException("Copula target is not a modeled variable.");target=index;if(term.factors().size()!=1&&!explicit)throw new IllegalArgumentException("A copula attached to a polynomial path needs explicit root adjustedCorrections naming the underlying endogenous variables.");if(term.factors().size()==1){Integer factor=identities.get(term.factors().getFirst());if(factor==null)throw new IllegalArgumentException("Copula source is not a modeled variable.");sourceIndex=factor;}}attachedTargets.add(target);if(!explicit&&sourceIndex>=0&&!requests.computeIfAbsent(target,key->new TreeSet<>()).add(sourceIndex))throw new IllegalArgumentException("Duplicate copula marker for the same variable/equation.");}}
        for(var link:document.links())if(link.type()==ElementType.CONNECTION_BETWEEN_GAUSSIAN_COPULA_AND_INDEPENT_TO_DEPENDENT_LV_CONNECTION&&document.node(link.source()).type()!=ElementType.GAUSSIAN_COPULA)throw new IllegalArgumentException("Copula attachments must start at a copula marker.");
        List<AdjustedCopula.Correction> corrections=new ArrayList<>();Map<Integer,Integer> binaryBindings=new LinkedHashMap<>();
        if(explicit){for(var entry:properties.getAsJsonArray("adjustedCorrections")){var object=entry.getAsJsonObject();int target=identity(object.get("target"),identities);var correction=new AdjustedCopula.Correction(target,identities(object.get("endogenous"),identities),identities(object.get("continuousExogenous"),identities),identities(object.get("binaryExogenous"),identities),DiagramModels.bool(object,"varyingByCategory",true));corrections.add(correction);for(int binary:correction.binaryExogenous()){Integer column=physical.get(binary);if(column==null)throw new IllegalArgumentException("Binary covariates require a single original indicator or fixed observed row function.");binaryBindings.put(binary,column);}}Set<Integer> targets=new HashSet<>();for(var correction:corrections)targets.add(correction.target());if(!targets.containsAll(attachedTargets))throw new IllegalArgumentException("Explicit corrections must retain every attached copula target.");}
        else{for(var request:requests.entrySet()){List<Integer> continuous=new ArrayList<>(),binary=new ArrayList<>();for(var edge:normalized)if(edge.target()==request.getKey()&&!request.getValue().contains(edge.source())){Integer column=physical.get(edge.source());boolean root=normalized.stream().noneMatch(path->path.target()==edge.source());if(root&&column!=null&&binary(source,column)){binary.add(edge.source());binaryBindings.put(edge.source(),column);}else continuous.add(edge.source());}corrections.add(new AdjustedCopula.Correction(request.getKey(),request.getValue().stream().mapToInt(Integer::intValue).toArray(),continuous.stream().mapToInt(Integer::intValue).toArray(),binary.stream().mapToInt(Integer::intValue).toArray(),DiagramModels.bool(properties,"varyCopulaByBinaryCategories",true)));}}
        List<PathProcess.Probe> probes=new ArrayList<>();if(properties.has("adjustedProbes"))for(var entry:properties.getAsJsonArray("adjustedProbes")){var probe=entry.getAsJsonObject();Map<Integer,Double> values=new LinkedHashMap<>();for(var value:probe.getAsJsonObject("values").entrySet()){Integer index=identities.get(value.getKey());if(index==null)throw new IllegalArgumentException("Probe variable identity is missing.");values.put(index,DiagramModels.number(value.getValue(),"Adjusted probe"));}probes.add(new PathProcess.Probe(DiagramModels.string(probe,"name",null),values));}
        var system=new AdjustedCopula.Model(names,paths,extensions,corrections,probes);for(var correction:corrections){Set<Integer> expected=new HashSet<>();for(var edge:normalized)if(edge.target()==correction.target())expected.add(edge.source());Set<Integer> classified=new HashSet<>();for(var roles:List.of(correction.endogenous(),correction.continuousExogenous(),correction.binaryExogenous()))for(int variable:roles)classified.add(variable);if(!expected.equals(classified)||expected.isEmpty())throw new IllegalArgumentException("Classify exactly the structural parents of every corrected equation.");}for(var binding:binaryBindings.entrySet()){if(normalized.stream().anyMatch(edge->edge.target()==binding.getKey()))throw new IllegalArgumentException("Binary covariates must be exogenous roots.");if(!binary(source,binding.getValue()))throw new IllegalArgumentException("Binary covariates must contain both original 0/1 categories.");}if(component==null)binaryBindings.clear();warnings.add("Root ADJUSTED_2025 explicitly selects the adjusted estimator for the full system; legacy marker CF/2sCOPE settings do not select this new estimator. All copula and polynomial requests are retained.");return new Compiled(document,component,system,source,binaryBindings,warnings);
    }
    private static int identity(JsonElement value,Map<String,Integer> identities){if(value==null||!value.isJsonPrimitive()||!value.getAsJsonPrimitive().isString()||!identities.containsKey(value.getAsString()))throw new IllegalArgumentException("Use existing stable variable node identities in adjustedCorrections.");return identities.get(value.getAsString());}
    private static int[] identities(JsonElement value,Map<String,Integer> identities){if(value==null)return new int[0];int[] result=new int[value.getAsJsonArray().size()];for(int i=0;i<result.length;i++)result[i]=identity(value.getAsJsonArray().get(i),identities);return result;}
    private static boolean binary(double[][] data,int column){boolean zero=false,one=false;for(var row:data){if(row[column]==0)zero=true;else if(row[column]==1)one=true;else return false;}return zero&&one;}
}
